#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include "md4c-html.h"

static void process_output(const MD_CHAR* text, MD_SIZE size, void* userdata){ (void)text;(void)size;(void)userdata; }

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size){
    unsigned parser_flags, renderer_flags;
    if(size < 2 * sizeof(unsigned)) return 0;
    parser_flags = ((unsigned*)data)[0];
    renderer_flags = ((unsigned*)data)[1];
    data += 2 * sizeof(unsigned);
    size -= 2 * sizeof(unsigned);
    md_html((const MD_CHAR*)data, (MD_SIZE)size, process_output, NULL, parser_flags, renderer_flags);
    return 0;
}

int main(int argc, char** argv){
    if(argc < 2){ fprintf(stderr,"usage: %s file\n", argv[0]); return 1; }
    FILE* f = fopen(argv[1], "rb");
    if(!f){ perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);
    uint8_t* buf = malloc(sz);
    fread(buf, 1, sz, f); fclose(f);
    int r = LLVMFuzzerTestOneInput(buf, sz);
    free(buf);
    return r;
}
